from django.db import migrations, models


def space_of(name: str, document: dict) -> str:
    """The space of a project made before spaces: a kitchen, a dressing or a placard, else a 3D design."""
    features = document.get("features") or []
    lower = name.lower()
    if any(f.get("kitchenPlan") is not None for f in features) or any(f.get("type") == "appliance" for f in features) or "cuisine" in lower:
        return "kitchen"
    if any(f.get("dressingPlan") is not None for f in features) or any(f.get("type") == "niche" for f in features) or "dressing" in lower or "placard" in lower:
        return "dressing"
    return "design"


def classify(apps, schema_editor):
    Project = apps.get_model("projects", "Project")
    Version = apps.get_model("projects", "ProjectVersion")
    for project in Project.objects.all():
        version = Version.objects.filter(project=project, number=project.current_version).first()
        space = space_of(project.name, version.document if version else {})
        if space != "design":
            # Not a change of the design: « modifié le » stays.
            Project.objects.filter(pk=project.pk).update(space=space)


